parameters.jsCode:
function getTriggerInput() {
  try { return $('Receive workflow call').first().json; } catch (error) {}
  try { return $('Receive request').first().json; } catch (error) {}
  return $json;
}
const inputRoot = getTriggerInput();
const input = inputRoot.body ?? inputRoot;
const ai = $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || input.live_probe?.request_id || 'req_' + executionId;
const aiText = ai.output || ai.text || ai.response || ai.message || '';
function safeJson(value) {
  if (value && typeof value === 'object') return value;
  const text = String(value || '').trim();
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = (fenced ? fenced[1] : text).trim();
  const firstBrace = candidate.indexOf('{');
  const lastBrace = candidate.lastIndexOf('}');
  if (firstBrace < 0 || lastBrace <= firstBrace) return null;
  try { return JSON.parse(candidate.slice(firstBrace, lastBrace + 1)); } catch { return null; }
}
const parsed = safeJson(aiText) || {};
const status = parsed.status || (parsed.okf_candidate ? 'candidate_ready' : parsed.next_question ? 'question_needed' : 'question_needed');
const response = {
  envelope_version: input.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'knowledge_retrieval_interviewer',
  status,
  approval: { required: false },
  output: {
    summary: parsed.summary || aiText || parsed.next_question || 'Knowledge Retrieval Interviewer produced the next elicitation step.',
    next_question: parsed.next_question || '',
    question_type: parsed.question_type || '',
    gap_being_closed: parsed.gap_being_closed || '',
    current_understanding: parsed.current_understanding || '',
    okf_candidate: parsed.okf_candidate || null,
    recommended_knowledge_fabric_action: parsed.recommended_knowledge_fabric_action || (parsed.okf_candidate ? 'stage_new_concept' : 'no_write'),
    contract_stage: 'ai_agent_normalized',
    ai_agent: { integrated: true, node: 'Knowledge Retrieval Interviewer AI Agent' }
  },
  trace: {
    stored: true,
    trace_id: 'n8n_exec_' + executionId,
    used_agents: ['knowledge_retrieval_interviewer'],
    target_agent: 'knowledge_retrieval_interviewer',
    route_decision: 'elicit_implicit_knowledge',
    handoff_status: status,
    parent_trace_id: input.context?.handoff_trace_id || input.context?.actor_trace_id || '',
    quality_gate_state: parsed.trace?.quality_gate_state || parsed.quality_gate_state || '',
    handoff_target: parsed.trace?.handoff_target || parsed.handoff_target || 'agentic_butler'
  }
};
return [{ json: response }];
